//! Admission rules for a recall nudge.
//!
//! Spec: `docs/cleanroom/specs/memory-recall-gate.md`. A nudge is a one-sentence hint pointing at a stored note.
//! The rules here exist because a nudge is generated by a sidecar model and then inserted into a live
//! conversation: it must be a *fact about a note*, never an instruction to the agent and never commentary on its
//! own usefulness. A hint reading "you should always run the smoke suite first" would arrive with the weight of
//! stored memory behind an instruction nobody approved.

use std::collections::BTreeSet;

use crate::recall_render::{NUDGE_HINT_MAX_CHARS, RecallNudge};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InvalidHintReason {
    Empty,
    TooLong,
    Multiline,
    DecisionCommentary,
    AddressesAgent,
}

pub fn describe_invalid_hint(hint: &str) -> Option<InvalidHintReason> {
    describe_hint_shape(hint).or_else(|| {
        if addresses_agent(hint) {
            Some(InvalidHintReason::AddressesAgent)
        } else {
            None
        }
    })
}

/// The replay half of the contract: shape only, without the nudge-only addressing rule.
///
/// Replay re-checks hints written by an older build. Those were already admitted under whatever rules existed
/// then, so applying today's addressing rule would silently drop history that was legitimate when written.
pub fn is_valid_hint(hint: &str) -> bool {
    describe_hint_shape(hint).is_none()
}

fn describe_hint_shape(hint: &str) -> Option<InvalidHintReason> {
    if hint.is_empty() {
        return Some(InvalidHintReason::Empty);
    }
    if hint.chars().count() > NUDGE_HINT_MAX_CHARS {
        return Some(InvalidHintReason::TooLong);
    }
    if hint.contains(['\r', '\n']) {
        return Some(InvalidHintReason::Multiline);
    }
    if has_decision_language(hint) {
        return Some(InvalidHintReason::DecisionCommentary);
    }
    None
}

fn addresses_agent(hint: &str) -> bool {
    let trimmed = hint.trim();
    has_second_person(trimmed)
        || has_imperative_opening(trimmed)
        || has_korean_request_ending(trimmed)
        || has_korean_prohibition(trimmed)
}

/// Alphanumeric word tokens, Unicode-aware: CJK text has no spaces, so split on character class rather than
/// whitespace or every CJK hint collapses into one token.
fn words_of(text: &str) -> Vec<String> {
    let lowered = text.to_lowercase();
    let mut words = Vec::new();
    let mut current = String::new();
    for ch in lowered.chars() {
        if ch.is_alphanumeric() {
            current.push(ch);
        } else if !current.is_empty() {
            words.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

const SECOND_PERSON: [&str; 4] = ["you", "your", "yours", "yourself"];

fn has_second_person(trimmed: &str) -> bool {
    words_of(trimmed)
        .iter()
        .any(|word| SECOND_PERSON.contains(&word.as_str()))
}

const IMPERATIVE_VERBS: [&str; 19] = [
    "do not",
    "don't",
    "don’t",
    "never",
    "always",
    "make sure",
    "ensure",
    "verify",
    "check",
    "run",
    "use",
    "read",
    "stop",
    "avoid",
    "remember",
    "keep",
    "prefer",
    "skip",
    "consider",
];

/// An opening verb, after any leading quotes and whitespace.
///
/// The verb must end at a word boundary: `runner` does not start with `run`, and `useful` does not start with
/// `use`, so a hint beginning with a noun is not rejected for looking like a command.
fn has_imperative_opening(hint: &str) -> bool {
    let trimmed = hint.trim_start_matches(|ch: char| {
        ch.is_whitespace()
            || matches!(
                ch,
                '"' | '\'' | '`' | '\u{00ab}' | '\u{2018}' | '\u{2019}' | '\u{201c}' | '\u{201d}'
            )
    });
    let collapsed: String = trimmed
        .to_lowercase()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    IMPERATIVE_VERBS.iter().any(|verb| {
        collapsed
            .strip_prefix(verb)
            .is_some_and(|rest| rest.chars().next().is_none_or(|ch| !ch.is_alphanumeric()))
    })
}

fn has_korean_request_ending(trimmed: &str) -> bool {
    let mut text = trimmed.trim_end();
    if let Some(stripped) = text.strip_suffix(['.', '!']) {
        text = stripped.trim_end();
    }
    const SUFFIXES: [&str; 6] = ["세요", "십시오", "십시요", "하라", "해라", "합니다"];
    if SUFFIXES.iter().any(|suffix| text.ends_with(suffix)) {
        return true;
    }
    let base = text.strip_suffix('라').unwrap_or(text);
    if let Some(rest) = base.strip_suffix('마') {
        return rest.trim_end().ends_with('지');
    }
    false
}

/// `하지 마` anywhere, with whitespace allowed before the final syllable.
fn has_korean_prohibition(text: &str) -> bool {
    let chars: Vec<char> = text.chars().collect();
    for (index, ch) in chars.iter().enumerate() {
        if *ch == '마' {
            let mut cursor = index;
            while cursor > 0 && chars[cursor - 1].is_whitespace() {
                cursor -= 1;
            }
            if cursor > 0 && chars[cursor - 1] == '지' {
                return true;
            }
        }
    }
    false
}

/// Commentary on whether a memory clears the bar is not a memory fact, and tells the model nothing it can use.
fn has_decision_language(hint: &str) -> bool {
    let lower = hint.to_lowercase();
    if lower.contains("no stored memory") || lower.contains("clears the bar") {
        return true;
    }
    let words = words_of(&lower);
    for (index, word) in words.iter().enumerate() {
        if (word == "no" || word == "not")
            && words.get(index + 1).is_some_and(|next| next == "relevant")
        {
            return true;
        }
        if word != "memory" && word != "memories" {
            continue;
        }
        match words.get(index + 1).map(String::as_str) {
            Some("is") | Some("are") => match (
                words.get(index + 2).map(String::as_str),
                words.get(index + 3).map(String::as_str),
            ) {
                (Some("unrelated"), Some("to")) | (Some("not"), Some("about")) => return true,
                _ => {}
            },
            Some("does") | Some("do")
                if words.get(index + 2).is_some_and(|next| next == "not")
                    && matches!(
                        words.get(index + 3).map(String::as_str),
                        Some("cover") | Some("address") | Some("pertain")
                    ) =>
            {
                return true;
            }
            Some("cover") | Some("covers")
                if words.get(index + 2..).is_some_and(|rest| {
                    rest.windows(2)
                        .any(|pair| pair[0] == "not" && pair[1] == "the")
                }) =>
            {
                return true;
            }
            _ => {}
        }
    }
    false
}

pub struct ValidateNudgesOptions {
    /// Paths the parent offered; anything else was fabricated by the sidecar.
    pub candidates: BTreeSet<String>,
    pub surfaced: BTreeSet<String>,
    pub max_items: usize,
}

/// Accept, in order, the nudges that pass every rule.
///
/// A rejected nudge is dropped silently rather than reported: the sidecar's output is untrusted, so a rejection
/// is routine, and surfacing it would let the sidecar put text in front of the user by getting itself rejected.
pub fn validate_nudges(
    nudges: &[RecallNudge],
    options: &ValidateNudgesOptions,
) -> Vec<RecallNudge> {
    if options.max_items == 0 {
        return Vec::new();
    }
    let mut accepted: Vec<RecallNudge> = Vec::new();
    let mut seen: BTreeSet<String> = BTreeSet::new();
    for nudge in nudges {
        if accepted.len() >= options.max_items {
            break;
        }
        if seen.contains(&nudge.path) {
            continue;
        }
        if !options.candidates.contains(&nudge.path) {
            continue;
        }
        if options.surfaced.contains(&nudge.path) {
            continue;
        }
        if describe_invalid_hint(&nudge.hint).is_some() {
            continue;
        }
        seen.insert(nudge.path.clone());
        accepted.push(nudge.clone());
    }
    accepted
}

#[cfg(test)]
mod tests {
    use super::*;

    fn nudge(path: &str, hint: &str) -> RecallNudge {
        RecallNudge::new(path, hint)
    }

    fn options(candidates: &[&str], surfaced: &[&str], max_items: usize) -> ValidateNudgesOptions {
        ValidateNudgesOptions {
            candidates: candidates.iter().map(|path| (*path).to_owned()).collect(),
            surfaced: surfaced.iter().map(|path| (*path).to_owned()).collect(),
            max_items,
        }
    }

    #[test]
    fn a_factual_hint_is_admitted() {
        assert!(describe_invalid_hint("The deploy gate requires a green smoke run.").is_none());
    }

    #[test]
    fn an_empty_hint_is_refused() {
        assert_eq!(describe_invalid_hint(""), Some(InvalidHintReason::Empty));
    }

    #[test]
    fn a_hint_at_the_budget_is_admitted() {
        let hint = "a".repeat(NUDGE_HINT_MAX_CHARS);
        assert!(describe_invalid_hint(&hint).is_none());
    }

    #[test]
    fn a_hint_over_the_budget_is_refused() {
        let hint = "a".repeat(NUDGE_HINT_MAX_CHARS + 1);
        assert_eq!(
            describe_invalid_hint(&hint),
            Some(InvalidHintReason::TooLong)
        );
    }

    #[test]
    fn the_budget_counts_characters_not_bytes() {
        let hint = "한".repeat(NUDGE_HINT_MAX_CHARS);
        assert!(describe_invalid_hint(&hint).is_none());
    }

    #[test]
    fn a_multiline_hint_is_refused() {
        assert_eq!(
            describe_invalid_hint("first line\nsecond"),
            Some(InvalidHintReason::Multiline)
        );
    }

    #[test]
    fn a_second_person_hint_addresses_the_agent() {
        assert_eq!(
            describe_invalid_hint("Your deploy runs nightly."),
            Some(InvalidHintReason::AddressesAgent)
        );
    }

    #[test]
    fn an_imperative_opening_addresses_the_agent() {
        assert_eq!(
            describe_invalid_hint("Run the smoke suite before deploying."),
            Some(InvalidHintReason::AddressesAgent)
        );
    }

    #[test]
    fn an_imperative_after_a_leading_quote_still_counts() {
        assert_eq!(
            describe_invalid_hint("\"Always deploy on Friday.\""),
            Some(InvalidHintReason::AddressesAgent)
        );
    }

    #[test]
    fn an_imperative_multi_word_opening_counts() {
        assert_eq!(
            describe_invalid_hint("Make sure the ledger is clean."),
            Some(InvalidHintReason::AddressesAgent)
        );
    }

    #[test]
    fn a_noun_that_merely_starts_with_an_imperative_verb_is_admitted() {
        assert!(describe_invalid_hint("Runners cache the toolchain.").is_none());
        assert!(describe_invalid_hint("Useful notes stay local.").is_none());
        assert!(describe_invalid_hint("Reading order matters here.").is_none());
    }

    #[test]
    fn a_korean_request_ending_addresses_the_agent() {
        for hint in [
            "배포 전에 확인하세요.",
            "배포 전에 확인하십시오",
            "배포 전에 확인합니다",
            "배포 전에 확인하라",
            "배포 전에 확인해라!",
        ] {
            assert_eq!(
                describe_invalid_hint(hint),
                Some(InvalidHintReason::AddressesAgent),
                "{hint}"
            );
        }
    }

    #[test]
    fn a_korean_prohibition_addresses_the_agent() {
        for hint in [
            "배포하지 마",
            "배포하지 마라",
            "배포 하지마.",
            "배포하지  마",
        ] {
            assert_eq!(
                describe_invalid_hint(hint),
                Some(InvalidHintReason::AddressesAgent),
                "{hint}"
            );
        }
    }

    #[test]
    fn a_korean_factual_hint_is_admitted() {
        assert!(describe_invalid_hint("배포 게이트는 스모크 검사가 통과해야 한다.").is_none());
    }

    #[test]
    fn a_statement_that_memory_is_unrelated_is_decision_commentary() {
        for hint in [
            "No relevant memory found.",
            "The memory is unrelated to this task.",
            "These memories are not about deployment.",
            "Memory does not cover this.",
            "The memories cover the deploy path, but not the rollback.",
            "Nothing here clears the bar.",
            "There is no stored memory for this.",
            "Not relevant.",
        ] {
            assert_eq!(
                describe_invalid_hint(hint),
                Some(InvalidHintReason::DecisionCommentary),
                "{hint}"
            );
        }
    }

    #[test]
    fn a_fact_that_mentions_memory_elsewhere_is_admitted() {
        assert!(
            describe_invalid_hint("The memory directory holds each session separately.").is_none()
        );
    }

    #[test]
    fn the_replay_rule_ignores_addressing() {
        assert!(is_valid_hint("Run the smoke suite."));
        assert!(!is_valid_hint(""));
        assert!(!is_valid_hint(&"a".repeat(NUDGE_HINT_MAX_CHARS + 1)));
    }

    #[test]
    fn only_offered_paths_are_accepted() {
        let accepted = validate_nudges(
            &[
                nudge("notes/a.md", "A fact."),
                nudge("notes/b.md", "A fact."),
            ],
            &options(&["notes/a.md"], &[], 5),
        );
        assert_eq!(accepted.len(), 1);
        assert_eq!(accepted[0].path, "notes/a.md");
    }

    #[test]
    fn a_surfaced_path_is_never_repeated() {
        let accepted = validate_nudges(
            &[nudge("notes/a.md", "A fact.")],
            &options(&["notes/a.md"], &["notes/a.md"], 5),
        );
        assert!(accepted.is_empty());
    }

    #[test]
    fn the_cap_is_enforced() {
        let accepted = validate_nudges(
            &[
                nudge("a.md", "A fact."),
                nudge("b.md", "A fact."),
                nudge("c.md", "A fact."),
            ],
            &options(&["a.md", "b.md", "c.md"], &[], 2),
        );
        assert_eq!(accepted.len(), 2);
    }

    #[test]
    fn a_zero_cap_accepts_nothing() {
        let accepted = validate_nudges(&[nudge("a.md", "A fact.")], &options(&["a.md"], &[], 0));
        assert!(accepted.is_empty());
    }

    #[test]
    fn a_duplicate_path_is_accepted_once() {
        let accepted = validate_nudges(
            &[nudge("a.md", "First."), nudge("a.md", "Second.")],
            &options(&["a.md"], &[], 5),
        );
        assert_eq!(accepted.len(), 1);
        assert_eq!(accepted[0].hint, "First.");
    }

    #[test]
    fn a_rejected_hint_does_not_consume_the_cap() {
        let accepted = validate_nudges(
            &[
                nudge("a.md", "Run this first."),
                nudge("b.md", "A factual note."),
            ],
            &options(&["a.md", "b.md"], &[], 1),
        );
        assert_eq!(accepted.len(), 1);
        assert_eq!(accepted[0].path, "b.md");
    }

    #[test]
    fn order_is_preserved() {
        let accepted = validate_nudges(
            &[
                nudge("c.md", "C fact."),
                nudge("a.md", "A fact."),
                nudge("b.md", "B fact."),
            ],
            &options(&["a.md", "b.md", "c.md"], &[], 5),
        );
        let paths: Vec<&str> = accepted.iter().map(|entry| entry.path.as_str()).collect();
        assert_eq!(paths, ["c.md", "a.md", "b.md"]);
    }

    #[test]
    fn the_accepted_nudge_carries_its_source() {
        let mut entry = nudge("a.md", "A fact.");
        entry.source = Some("readable/a.md".to_owned());
        let accepted = validate_nudges(&[entry], &options(&["a.md"], &[], 1));
        assert_eq!(accepted[0].source.as_deref(), Some("readable/a.md"));
    }
}
